                // every arg position by one and the canonical
                // `bless \(my $z = $_[1]), $_[0]` body would build the
                // wrong object.
                let mut init_args: Vec<Value> = vec![Value::Str(class.clone())];
                init_args.extend(args[2..].iter().flat_map(|a| self.eval_list(a)));
