                // Auto-seeds on first call (Perl semantics).
                if self.rand_seed.is_none() {
                    self.auto_seed_rand();
                }
                let limit = if args.is_empty() {
                    1.0
                } else {
                    let v = self.eval_expr(&args[0]).to_num();
                    if v == 0.0 { 1.0 } else { v.abs() }
                };
                let r = self.next_rand_unit();
                Value::Num(r * limit)
